const walkthroughs=[{"body": "All\u2011or\u2011nothing payment settings force firms to choose between staying in control and offering convenience to their clients.", "heading": "Payments shouldn\u2019t be a trade\u2011off", "media": "assets/b209d8511148ceb5", "tabs": [{"body": "The right payment methods vary by client, matter, and firm policy. Turn card, ACH, or financing on or off for individual invoices, so every payment request fits.", "title": "Choose which payment methods appear on invoices"}, {"body": "When a client opens a payment request, they only see the options chosen for that invoice. The checkout experience stays intuitive and professional.", "title": "Clients only see what the firm approves"}], "title": "Give clients convenience. Keep control.", "tldr": "Choose exactly which payment options appear on every invoice."}, {"body": "Every day, legal professionals lose hours piecing together case details and running reports to see firm\u2011wide insights.", "heading": "One conversation", "media": "assets/5693b3dfc382f80e", "tabs": [{"body": "Firm Agent knows your whole firm and provides a complete morning brief, so you can proceed with the confidence that comes with staying on top of all tasks and deadlines.", "title": "Start the day already caught up"}, {"body": "Which cases have overdue invoices? Which leads need follow up? How much does this client owe?", "title": "One answer without running three reports"}, {"body": "Overdue invoices across all active matters. Cases with no billed time in 60 days. Workload by practice area. Just ask, and Firm Agent finds what needs attention now.", "title": "Spot issues before they become problems"}, {"body": "Firm owners and administrators see all matters and full financials. Attorneys see their own. Paralegals see permitted matters with financials blocked. Firm Agent enforces the same role permissions already set in MyCase.", "title": "Everyone sees only what they need"}], "title": "Confidence starts with firm\u2011wide clarity", "tldr": "From a morning brief of what\u2019s due today to where your firm should grow next, Firm Agent answers it all in one conversation."}, {"body": "Without OCR, scanned PDFs, JPGs, PNGs, and TIFFs sit in your system as image files, invisible to search.", "heading": "It\u2019s in the details", "media": "assets/08eb63c7b6ec5d50", "tabs": [{"body": "With built-in OCR, every image-based file is automatically converted into readable, searchable text. Passports. Court records. 200-page PDFs from opposing counsel. Nothing gets missed.", "title": "Now every file is searchable"}, {"body": "OCR runs automatically the moment a document is uploaded to MyCase. No conversion step, no third-party tools, no re-upload. The file is searchable as soon as it\u2019s in the system.", "title": "No juggling add ons. No extra steps."}, {"body": "Search case data with confidence, knowing Discovery Assistant ensures important details aren\u2019t overlooked.", "title": "Search results you can rely on"}], "title": "Every file searchable. Every insight sharper.", "tldr": "Somewhere in your scanned files is the information you need. Discovery Assistant makes sure you find it."}, {"body": "Poor communication is a top driver of bar complaints. Case Assistant drafts client updates that keep clients informed and the firm protected.", "heading": "A leading bar complaint addressed", "media": "assets/6c7851bcbf99ace3", "tabs": [{"body": "Case Assistant spans case facts, documents, and financials to answer any query. Ask \"Where do we stand financially on this matter?\" and get a clear answer, with complete case context.", "title": "Case answers you can trust"}, {"body": "With financial data fully integrated, Case Assistant can surface where case financials stand instantly \u2014 balances, unbilled work, invoice status \u2014 without digging through a single report.", "title": "Financial answers when you need them"}, {"body": "A built-in prompt library lets you save and reuse your most effective queries. Get consistent answers without starting from scratch or trying to remember what worked last time.", "title": "Consistent prompts that yield faster results"}, {"body": "Case Assistant brings in relevant case details to draft client messages. Review and send directly from the chat. No switching tabs, no lost context.", "title": "Draft it. Send it. Never leave the chat."}], "title": "Ask, draft, send. All in one chat.", "tldr": "Ask matter details, get a historical timeline, and draft and send a client message, all without leaving your case conversation."}, {"body": "Getting an answer from your own data means running reports, exporting them, and clicking through tab after tab. Most firms just live with it, and none of that time is billable.", "heading": "Answers shouldn\u2019t be this hard to find", "media": "assets/c414489f094e2fbd", "tabs": [{"body": "MyCase MCP connects your firm data directly to Claude. Every answer comes from your firm\u2019s own records, not a generic AI guess. Get answers fast, without the manual search or copy and paste.", "title": "Move casework forward faster"}, {"body": "No more exports, copy-pasting, or stale spreadsheets. Just live data, straight from MyCase.", "title": "Data without the legwork"}, {"body": "Ask Claude about your firm\u2019s staff, productivity, or revenue across every matter. Check unbilled hours, outstanding invoices, or get a fast read on which practice areas are the most profitable.", "title": "Clear, firm-wide insights"}, {"body": "Every connection between MyCase and Claude respects the rules your practice already runs on and aligns with 8am data protection standards.", "title": "You stay protected and in control"}], "title": "Close the gap between data and action", "tldr": "When Claude reads data from MyCase, it becomes context Claude carries into everything, from casework to insights about firm profitability and growth opportunities."}, {"body": "There\u2019s no time to send updates on every open matter. Client message templates and AI drafting close that gap, making it easy to stay on top of regular, proactive client updates.", "heading": "It\u2019s a bandwidth gap", "media": "assets/32507f8eeb40c955", "tabs": [{"body": "Clients who hear from you regularly trust you more and call less. Message templates handle the routine updates. Case Assistant drafts the custom ones, so every client stays reassured.", "title": "An informed client is a confident client"}, {"body": "Case Assistant references full case context to customize each client message while templates automatically pull in client names and specific details.", "title": "Every message feels personal"}, {"body": "Firm-approved templates mean every staff member sends communications that reflect the firm\u2019s tone and standards. New hires get up to speed faster. Nothing off brand goes out.", "title": "One template library for the whole team"}, {"body": "Your templates work today. As automated sends roll out, the same templates you\u2019ve already built will start firing on their own at key case milestones, no extra setup required.", "title": "Built to keep getting better"}], "title": "Sending client updates just got easier", "tldr": "Message templates and AI drafts get you to \"sent\" faster."}, {"body": "Drafting is crucial for firms, but it eats hours. Time disappears into building templates and wrestling with Word.", "heading": "Drafting is its own job", "media": "assets/012892dd3bff3ce9", "tabs": [{"body": "Upload a document you already use, and 8am IQ Draft turns it into a ready-to-use template, complete with relevant fields. It stays true to your original, so you can trust every document you send.", "title": "Templates created for you"}, {"body": "Instead of starting from a blank page, describe what you need and IQ Draft creates a template for you to review and edit.", "title": "Seconds from your first draft"}, {"body": "Matter details come straight from MyCase and formula fields do the math. No manual work, no triple-checking, just confidence in the finished document.", "title": "Populates from case data and runs the numbers"}, {"body": "Generate a complete, matter-specific document right in your browser, without needing to open Word. Finished documents save back to the matter.", "title": "Stay in MyCase from start to finish"}], "title": "Documents that build themselves", "tldr": "Easily turn blank pages and precedent documents into templates that auto-populate using your MyCase data."}, {"body": "Firms quietly absorb hard costs not linked to a case, instead of billing the client.", "heading": "Unlinked expenses mean missed reimbursements", "media": "assets/87ff4b110508c7c1", "tabs": [{"body": "Full visibility into every case expense. Tracked and recovered automatically with Smart Spend.", "title": "Integrated spend management. Total financial clarity."}, {"body": "Smart Spend Intelligence surfaces the most likely case for an expense based on recent activity, reducing a multi-step search to a single click.", "title": "Faster case matching"}, {"body": "With expense insights right on your dashboard, review spend attribution and turn lost billables into actionable numbers.", "title": "Billing insights without data diving"}], "title": "Recover more of what you\u2019re owed", "tldr": "Connect spend to cases with a click. One dashboard shows what\u2019s tracked in advanced costs. Nothing gets missed."}, {"body": "Delayed client payments. Advanced client expenses. Uneven revenue. Law firms operate with inherently variable cash flow profiles that traditional lenders often struggle to evaluate.", "heading": "Traditional lending is complicated", "media": "assets/bf5132a8955d6208", "tabs": [{"body": "Applications live inside 8am with decisions in minutes and funding in 1-2 business days. Repayments happen automatically as revenue comes in.", "title": "Funding in days"}, {"body": "Approval is based on firm revenue and three months of payment history. Review pre-qualified offers with no credit check.", "title": "No impact to credit"}, {"body": "Growth, cash flow or scaling up, 8am Capital is built to fund the next stage of the business you\u2019ve built.", "title": "Your revenue, now working as capital"}], "title": "Capital when you need\u00a0it", "tldr": "Traditional lenders check your credit. 8am Capital checks your revenue, and offers funds in days, not months."}, {"body": "When a client doesn\u2019t have the cash they need, firms choose between discounting, carrying a payment plan, or waiting. Each option costs time, money, or both.", "heading": "Firms leave money on the table", "media": "assets/2acfa7df0eecfea4", "tabs": [{"body": "Eligible clients apply for financing at checkout through Affirm and get an instant decision, with no impact to their credit score. Approved clients repay over time, on amounts from $150 to $30,000.", "title": "Clients apply and get an answer in minutes"}, {"body": "When a client uses financing, you receive the invoiced amount by ACH within one to five business days. Repayment happens between the client and Affirm, so you\u2019re not liable for collecting on the loan.", "title": "Get paid upfront and Affirm handles the rest"}, {"body": "You decide which invoices offer financing. When Pay Later is enabled, the client sees it at checkout and chooses from there.", "title": "Flexibility you control"}], "title": "Client flexibility without delaying\u00a0payment", "tldr": "Your clients pay over time while you collect funds up front."}, {"body": "Most payments start with setup: find the contact, open the case, create the invoice. These tasks stand between firms and their money.", "heading": "Setup delays are payment delays", "media": "assets/4bfc97640e403358", "tabs": [{"body": "Take a payment from the home or billing dashboard, with no invoice, case, or contact required. Quick charge is the shortest path to paid, whether the client is new or one you\u2019ve billed for years.", "title": "Collect a payment in one step"}, {"body": "When a new client pays, their contact is created automatically, so your records stay clean without slowing you down. Each payment routes to the right trust, credit, or operating account in the flow.", "title": "Speed with Compliance"}], "title": "The easiest way to collect a payment", "tldr": "Collect any payment from your dashboard with no invoice or case required."}, {"body": "Everyone starts their workday differently. When the default is the same for every role, you scroll past what doesn\u2019t apply to you to find what does. That clutter steals your focus.", "heading": "One size doesn\u2019t fit all", "media": "assets/8f6d58b31fb8eddf", "tabs": [{"body": "Show, hide and rearrange widgets on your home and billing dashboards. Reconfigure your layout whenever your priorities shift.", "title": "Personalize in seconds"}, {"body": "See what you need as soon as you log in: a to-do list, unread messages, a financial overview, whatever matters to you. Nothing to dig through.", "title": "Less clutter, more focus"}], "title": "Your dashboard, your way", "tldr": "Firm staff can customize their own dashboards to surface what\u2019s most relevant to them."}, {"body": "Firms plan better knowing exactly when their money lands. Predictable deposit timing means payroll gets covered, expenses get managed, and growth decisions get made with real numbers, not estimates.", "heading": "Cash flow is king", "media": "assets/f25cf4d2447e4640", "tabs": [{"body": "For eligible firms, next-day deposits are standard. No activation, no added cost, nothing to turn on.", "title": "Get funds by the next business morning"}, {"body": "When funds arrive the next business day, payroll, vendors, and growth decisions run on certainty instead of estimates. Every payment feature works exactly as it does now, still fully IOLTA and PCI compliant.", "title": "Confident planning starts with predictable payments"}], "title": "Yesterday\u2019s payments in hand today", "tldr": "Two to three days becomes one. No setup, no fee, no guessing when funds will arrive."}, {"body": "Clients increasingly expect to pay in seconds from their phone. Make them dig out a card and type it in, and you\u2019ll wait longer to get paid.", "heading": "Extra steps slow payments", "media": "assets/a76798732d5dd7a8", "tabs": [{"body": "Clients pay from their Apple device with Face ID, Touch ID, or a passcode. For those who already use Apple Pay, there\u2019s nothing to enter and nothing to look up.", "title": "Skip the typing"}, {"body": "Apple Pay funds land in the right accounts with clean reconciliation, so you get the convenience without the IOLTA risk.", "title": "Convenience and compliance"}, {"body": "Paying on mobile is more intuitive than ever. Fewer steps, fewer drop-offs and fewer \"did you get it?\" calls for your firm.", "title": "A better experience from request to receipt"}], "title": "Getting paid is faster than ever", "tldr": "When paying is this quick and easy, clients don\u2019t delay."}];